import{_ as e,c as r,o as i,ah as h}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"第六卦 訟 天水訟 乾上坎下","description":"周易 - 第六卦 訟 天水訟 乾上坎下","frontmatter":{"title":"第六卦 訟 天水訟 乾上坎下","description":"周易 - 第六卦 訟 天水訟 乾上坎下"},"headers":[],"relativePath":"classics/zhouyi/007.md","filePath":"classics/zhouyi/007.md"}'),l={name:"classics/zhouyi/007.md"};function t(n,a,s,d,o,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="訟" tabindex="-1">訟 <a class="header-anchor" href="#訟" aria-label="Permalink to “訟”">​</a></h1><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>有孚，窒。惕中吉。終兇。利見大人，不利涉大川。</p><h3 id="彖傳" tabindex="-1">彖傳 <a class="header-anchor" href="#彖傳" aria-label="Permalink to “彖傳”">​</a></h3><p>訟，上剛下險，險而健訟。訟有孚窒，惕中吉，剛來而得中也。終兇；訟不可成也。利見大人；尚中正也。不利涉大川；入於淵也。</p><h3 id="象傳" tabindex="-1">象傳 <a class="header-anchor" href="#象傳" aria-label="Permalink to “象傳”">​</a></h3><p>天與水違行，訟；君子以作事謀始。</p><h3 id="初六" tabindex="-1">初六 <a class="header-anchor" href="#初六" aria-label="Permalink to “初六”">​</a></h3><p>不永所事，小有言，終吉。象曰：不 永所事，訟不可長也。雖有小言，其辯明也。</p><h3 id="九二" tabindex="-1">九二 <a class="header-anchor" href="#九二" aria-label="Permalink to “九二”">​</a></h3><p>不克訟，歸而逋，其邑人三百戶，無眚。象曰：不克訟，歸而逋也。自下訟上，患至掇也。</p><h3 id="六三" tabindex="-1">六三 <a class="header-anchor" href="#六三" aria-label="Permalink to “六三”">​</a></h3><p>食舊德，貞厲，終吉，或從王事，無成。象曰：食舊德，從上吉也。</p><h3 id="九四" tabindex="-1">九四 <a class="header-anchor" href="#九四" aria-label="Permalink to “九四”">​</a></h3><p>不克訟，復自命，渝安貞，吉。象曰：復即命，渝安貞；不失也。</p><h3 id="九五" tabindex="-1">九五 <a class="header-anchor" href="#九五" aria-label="Permalink to “九五”">​</a></h3><p>訟元吉。象曰：訟元吉，以中正也。</p><h3 id="上九" tabindex="-1">上九 <a class="header-anchor" href="#上九" aria-label="Permalink to “上九”">​</a></h3><p>或錫之鞶帶，終朝三褫之。象曰：以訟受服，亦不足敬也。</p>',19)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
